#include <cstddef>
#include <cstdint>
namespace {
void put_i64(std::uint8_t*out,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t i=0;i<8;i++)out[i]=static_cast<std::uint8_t>(b>>(8*i));}
int lca(int n,int*m,int*p,int*b,int a,int c){bool seen[12]{};while(true){a=b[a];seen[a]=true;if(m[a]<0)break;a=p[m[a]];}while(true){c=b[c];if(seen[c])return c;c=p[m[c]];}}
void mark_path(int*m,int*p,int*b,bool*bl,int v,int root,int child){while(b[v]!=root){bl[b[v]]=true;bl[b[m[v]]]=true;p[v]=child;child=m[v];v=p[m[v]];}}
bool find_path(int n,bool*adj,int*m,int*p,int*b,int root){bool used[12]{};int q[12],head=0,tail=0;for(int i=0;i<n;i++){p[i]=-1;b[i]=i;}q[tail++]=root;used[root]=true;while(head<tail){int v=q[head++];for(int u=0;u<n;u++){if(!adj[v*12+u]||b[v]==b[u]||m[v]==u)continue;if(u==root||(m[u]>=0&&p[m[u]]>=0)){int cur=lca(n,m,p,b,v,u);bool bl[12]{};mark_path(m,p,b,bl,v,cur,u);mark_path(m,p,b,bl,u,cur,v);for(int i=0;i<n;i++)if(bl[b[i]]){b[i]=cur;if(!used[i]){used[i]=true;q[tail++]=i;}}}else if(p[u]<0){p[u]=v;if(m[u]<0){int x=u;while(x>=0){int pv=p[x],next=pv>=0?m[pv]:-1;if(pv>=0){m[x]=pv;m[pv]=x;}x=next;}return true;}int mate=m[u];used[mate]=true;q[tail++]=mate;}}}return false;}
}
extern "C" std::int64_t general_graph_maximum_matching(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<2||len>134)return -1;auto n0=in[0],m0=in[1];if(n0<2||n0>12||m0<0||m0>n0*(n0-1)/2||len!=2+2*static_cast<std::size_t>(m0))return -1;int n=static_cast<int>(n0),m=static_cast<int>(m0);bool adj[144]{};for(int e=0;e<m;e++){auto u0=in[2+2*e],v0=in[3+2*e];if(u0<0||v0<=u0||v0>=n0)return -1;int u=static_cast<int>(u0),v=static_cast<int>(v0);if(adj[u*12+v])return -1;adj[u*12+v]=adj[v*12+u]=true;}int match[12],parent[12],base[12];for(int i=0;i<n;i++)match[i]=-1;for(int i=0;i<n;i++)if(match[i]<0)find_path(n,adj,match,parent,base,i);std::int64_t count=0;for(int i=0;i<n;i++)if(match[i]>i)count++;if(!out||cap<8)return -2;put_i64(out,count);return 8;}
